let rankingAccount=null,rankingConfig=null,rankingPending=false;
async function rankingRequest(path,body){let response=await fetch('/api/'+path,{credentials:'same-origin',...(body!==undefined?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});let result;try{result=await response.json()}catch{throw Error('ランキングは現在接続できません')}if(!response.ok)throw Error(result.error||'ランキングに接続できません');return result}
async function renderRanking(){let box=$('accountRanking');if(!box)return;try{rankingConfig=await rankingRequest('config');if(!rankingConfig.ready){box.textContent='Googleランキングは設定待ちです。端末内のDPS測定は利用できます。';return}rankingAccount=await rankingRequest('me');let data=await rankingRequest('ranking');if(menuSurface!=='dps'||!box.isConnected)return;box.innerHTML='<h3>アカウントDPSランキング</h3>'+(rankingAccount?'<p>'+gearEscape(rankingAccount.name)+' <button onclick="rankingLogout()">ログアウト</button></p>':'<button onclick="rankingLogin()">Googleでログイン</button><div id="googleSignIn"></div>')+(data.mine?'<p>今回 '+data.mine.last.toLocaleString()+' DPS · 自己ベスト '+data.mine.best.toLocaleString()+' · '+data.mine.rank+'位</p>':'<p>ログインしてチャレンジすると記録できます。</p>')+'<ol>'+data.leaders.map(row=>'<li>'+gearEscape(row.name)+' <strong>'+row.dps.toLocaleString()+' DPS</strong></li>').join('')+'</ol><small>同じ調整版の記録を比較。通常ランキング（ゲーム内計測値）。Googleの名前やメールアドレスは表示しません。</small>'}catch{if(box.isConnected)box.textContent='共有ランキングは未接続です。端末内の今回のDPSと自己ベストを表示しています。'}}
async function rankingLogin(){if(!rankingConfig?.ready)return;let box=$('googleSignIn');if(!box)return;box.textContent='Googleログインを準備しています…';try{let {nonce}=await rankingRequest('login-challenge',{});if(!window.google?.accounts?.id)await new Promise((resolve,reject)=>{let script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.onload=resolve;script.onerror=reject;document.head.append(script)});if(!box.isConnected)return;box.textContent='';window.google.accounts.id.initialize({client_id:rankingConfig.clientId,nonce,callback:async response=>{try{await rankingRequest('login',{credential:response.credential});await renderRanking()}catch(error){say(error.message)}}});window.google.accounts.id.renderButton(box,{theme:'outline',size:'large',text:'signin_with'})}catch{box.textContent='ログインを開始できません。再度お試しください。'}}
async function rankingLogout(){try{await rankingRequest('logout',{});rankingAccount=null;await renderRanking()}catch(error){say(error.message)}}
const rankingDpsMenu=showDps;showDps=()=>{rankingDpsMenu();renderRanking()};
const rankingDpsStart=beginDps;beginDps=async()=>{if(rankingPending||!villageOpen||document.hidden||!padWindowActive)return;let ticket=null,focusEpoch=typeof inputFocusEpoch==='number'?inputFocusEpoch:0;rankingPending=true;try{if(rankingAccount){ticket=await rankingRequest('dps/start',{});if(menuSurface!=='dps'||!villageOpen||document.hidden||!padWindowActive||focusEpoch!==(typeof inputFocusEpoch==='number'?inputFocusEpoch:0))return}rankingDpsStart();if(dpsRun)dpsRun.ticket=ticket}catch(error){say(error.message)}finally{rankingPending=false}};
const rankingDpsFinish=finishDps;finishDps=()=>{let run=dpsRun,ticket=run?.ticket,wasActive=!!run?.active;rankingDpsFinish();if(ticket&&wasActive)rankingRequest('dps/finish',{id:ticket.id,damage:run.damage,season:ticket.season}).then(()=>{if(menuSurface==='dps')renderRanking()}).catch(error=>say(error.message))};
